public static void removeAll(Stack<Integer> s, int x) {
    Stack<Integer> temp = new Stack<Integer>();
    while (!s.isEmpty()) {
        int y = s.pop();
        if (y != x) {
            temp.push(y);
        }
    }
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
}

public static void insertBottom(Stack<Integer> s, int x) {
    Stack<Integer> temp = new Stack<Integer>();
    while (!s.isEmpty()) {
        temp.push(s.pop());
    }
    s.push(x);
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
}

